import (
	"fmt"
	"strings"
	"unicode"
)

func validatePassword(p string) string {
	if len(p) < 8 {
		return "kamida 8 belgi bo'lishi kerak"
	}
	if !strings.ContainsFunc(p, unicode.IsDigit) {
		return "kamida bitta raqam bo'lishi kerak"
	}
	if !strings.ContainsFunc(p, unicode.IsUpper) {
		return "kamida bitta katta harf bo'lishi kerak"
	}
	return "parol kuchli"
}

func main() {
	fmt.Println(validatePassword("salom"))
	fmt.Println(validatePassword("salomdunyo"))
	fmt.Println(validatePassword("salomdunyo7"))
	fmt.Println(validatePassword("SalomDunyo7"))
}

package main

import "fmt"

type Order struct {
	Total    float64
	IsMember bool
}

func discount(o Order) float64 {
	rate := 0.0
	if o.Total >= 1_000_000 {
		rate = 0.10
	} else if o.Total >= 500_000 {
		rate = 0.05
	}
	if o.IsMember {
		rate += 0.02
	}
	return o.Total * rate
}

func main() {
	fmt.Printf("%.0f\n", discount(Order{Total: 300_000}))
	fmt.Printf("%.0f\n", discount(Order{Total: 600_000, IsMember: true}))
	fmt.Printf("%.0f\n", discount(Order{Total: 1_200_000}))
}

