type User struct {
	Login    string
	Password string
	Active   bool
}

func login(u User, password string) error {
	if !u.Active {
		return errors.New("hisob bloklangan")
	}
	if u.Password != password {
		return errors.New("parol noto'g'ri")
	}
	return nil
}

func main() {
	aziz := User{Login: "aziz", Password: "1234", Active: true}
	if err := login(aziz, "0000"); err != nil {
		fmt.Println("xato:", err)
	}
	if err := login(aziz, "1234"); err == nil {
		fmt.Println("xush kelibsiz,", aziz.Login)
	}
}

