import (
	"errors"
	"fmt"
)

func withdraw(balance, amount int) (int, error) {
	if amount <= 0 {
		return balance, errors.New("summa musbat bo'lishi kerak")
	}
	if amount > balance {
		return balance, errors.New("mablag' yetarli emas")
	}
	return balance - amount, nil
}

func main() {
	balance := 100
	for _, amount := range []int{30, 500, -5} {
		newBalance, err := withdraw(balance, amount)
		if err != nil {
			fmt.Println("xato:", err)
			continue
		}
		balance = newBalance
		fmt.Println("yechildi:", amount, "qoldiq:", balance)
	}
}

