package main

import "fmt"

type Order struct {
	ID      int
	Qty     int
	Price   float64
	Address string
}

func validate(o Order) string {
	if o.Qty <= 0 {
		return fmt.Sprintf("#%d: miqdor noto'g'ri", o.ID)
	}
	if o.Price <= 0 {
		return fmt.Sprintf("#%d: narx noto'g'ri", o.ID)
	}
	if o.Address == "" {
		return fmt.Sprintf("#%d: manzil yo'q", o.ID)
	}
	return fmt.Sprintf("#%d: OK, jami %.2f", o.ID, float64(o.Qty)*o.Price)
}

func main() {
	orders := []Order{
		{1, 2, 15.5, "Toshkent"},
		{2, 0, 10, "Buxoro"},
		{3, 1, 99.99, ""},
	}
	for _, o := range orders {
		fmt.Println(validate(o))
	}
}

