func gradeWrong(score int) string {
	if score >= 60 {
		return "C" // keng shart birinchi — A va B ga hech qachon yetib kelmaydi
	} else if score >= 75 {
		return "B"
	} else if score >= 90 {
		return "A"
	}
	return "F"
}

func gradeRight(score int) string {
	if score >= 90 {
		return "A"
	} else if score >= 75 {
		return "B"
	} else if score >= 60 {
		return "C"
	}
	return "F"
}

func main() {
	fmt.Println("noto'g'ri tartib:", gradeWrong(95), gradeWrong(80))
	fmt.Println("to'g'ri tartib:  ", gradeRight(95), gradeRight(80))
}

