func writeNotes(path string) (err error) {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer func() {
		if cerr := f.Close(); cerr != nil && err == nil {
			err = cerr // Close xatosini ham yo'qotmaymiz
		}
	}()
	_, err = f.WriteString("salom\ndunyo\n")
	return err
}

