	"slices"
	"sync"
)

func worker(id int, wg *sync.WaitGroup, results chan<- string) {
	defer wg.Done()
	defer func() {
		if r := recover(); r != nil {
			results <- fmt.Sprintf("worker %d tiklandi: %v", id, r)
		}
	}()
	if id == 2 {
		panic("buzilgan vazifa")
	}
	results <- fmt.Sprintf("worker %d tugadi", id)
}

func main() {
	var wg sync.WaitGroup
	results := make(chan string, 3)
	for id := 1; id <= 3; id++ {
		wg.Add(1)
		go worker(id, &wg, results)
	}
	wg.Wait()
	close(results)

	var lines []string
	for r := range results {
		lines = append(lines, r)
	}
	slices.Sort(lines)
	for _, l := range lines {
		fmt.Println(l)
	}
}

