import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

func recoverMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if rec := recover(); rec != nil {
				http.Error(w, fmt.Sprint("ichki xato: ", rec), http.StatusInternalServerError)
			}
		}()
		next(w, r)
	}
}

func main() {
	handler := recoverMiddleware(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/boom" {
			panic("handler yiqildi")
		}
		fmt.Fprintln(w, "salom")
	})
	srv := httptest.NewServer(handler)
	defer srv.Close()

	for _, path := range []string{"/", "/boom"} {
		resp, _ := http.Get(srv.URL + path)
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%s → %d %s", path, resp.StatusCode, body)
	}
}

