import "fmt"

func countWithGoto(s string) (letters, digits int) {
	i := 0
next:
	if i < len(s) {
		if s[i] >= '0' && s[i] <= '9' {
			digits++
		} else {
			letters++
		}
		i++
		goto next
	}
	return
}

func countWithFor(s string) (letters, digits int) {
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			digits++
		} else {
			letters++
		}
	}
	return
}

func main() {
	fmt.Println(countWithGoto("ab12cd"))
	fmt.Println(countWithFor("ab12cd"))
}

