import "fmt"

func collatzSteps(n int) int {
	steps := 0
	for {
		if n == 1 {
			break
		}
		if n%2 == 0 {
			n /= 2
		} else {
			n = 3*n + 1
		}
		steps++
	}
	return steps
}

func main() {
	for _, n := range []int{6, 7, 27} {
		fmt.Println(n, "→", collatzSteps(n), "qadam")
	}
}

